// THANKS: https://github.com/Wikiki/bulma-tooltip

$tooltip-arrow-size: 6px !default;
$tooltip-background-color: $grey-dark !default;
$tooltip-background-opacity: 0.9 !default;
$tooltip-color: $white !default;
$tooltip-font-family: $family-primary !default;
$tooltip-font-size: $size-7 !default;
$tooltip-max-width: 15rem !default;
$tooltip-padding: .5rem 1rem !default;
$tooltip-radius: $radius-small !default;
$tooltip-z-index: 9999 !default;

@mixin tooltip-hover {
	&:focus::before,
	&:focus::after,
	&:hover::before,
	&:hover::after,
	&.has-tooltip-active::before,
	&.has-tooltip-active::after {
		@content; } }

@mixin tooltip-arrow-top {
	&::after {
		top: 0;
		right: auto;
		bottom: auto;
		left: 50%;
		margin-top: $tooltip-arrow-size * -1 + 1;
		margin-right: auto;
		margin-bottom: auto;
		margin-left: $tooltip-arrow-size * -1 + 1;
		border-color: rgba($tooltip-background-color, $tooltip-background-opacity) transparent transparent transparent; } }

@mixin tooltip-box-top {
	&::before {
		top: 0;
		right: auto;
		bottom: auto;
		left: 50%;
		margin-top: $tooltip-arrow-size * -1 + 1;
		margin-bottom: auto;
		@include translate(-50%, -100%); } }

@mixin tooltip-top {
	@include tooltip-arrow-top;
	@include tooltip-box-top; }

@mixin tooltip-arrow-bottom {
	&::after {
		top: auto;
		right: auto;
		bottom: 0;
		left: 50%;
		margin-top: auto;
		margin-right: auto;
		margin-bottom: $tooltip-arrow-size * -1 + 1;
		margin-left: $tooltip-arrow-size * -1 + 1;
		border-color: transparent transparent rgba($tooltip-background-color, $tooltip-background-opacity) transparent; } }

@mixin tooltip-box-bottom {
	&::before {
		top: auto;
		right: auto;
		bottom: 0;
		left: 50%;
		margin-top: auto;
		margin-bottom: $tooltip-arrow-size * -1 + 1;
		@include translate(-50%, 100%); } }

@mixin tooltip-bottom {
	@include tooltip-arrow-bottom;
	@include tooltip-box-bottom; }


@mixin tooltip-arrow-left {
	&::after {
		top: auto;
		right: auto;
		bottom: 50%;
		left: 0;
		margin-top: auto;
		margin-right: auto;
		margin-bottom: $tooltip-arrow-size * -1;
		margin-left: $tooltip-arrow-size * -2 + 1;
		border-color: transparent transparent transparent rgba($tooltip-background-color, $tooltip-background-opacity); } }

@mixin tooltip-box-left {
	&::before {
		top: auto;
		right: auto;
		bottom: 50%;
		left: $tooltip-arrow-size * -2 + 1;
		@include translate(-100%, 50%); } }

@mixin tooltip-left {
	@include tooltip-arrow-left;
	@include tooltip-box-left; }


@mixin tooltip-arrow-right {
	&::after {
		top: auto;
		right: 0;
		bottom: 50%;
		left: auto;
		margin-top: auto;
		margin-right: $tooltip-arrow-size * -2 + 1;
		margin-bottom: $tooltip-arrow-size * -1;
		margin-left: auto;
		border-color: transparent rgba($tooltip-background-color, $tooltip-background-opacity) transparent transparent; } }

@mixin tooltip-box-right {
	&::before {
		top: auto;
		right: $tooltip-arrow-size * -2 + 1;
		bottom: 50%;
		left: auto;
		margin-top: auto;
		@include translate(100%, 50%); } }

@mixin tooltip-right {
	@include tooltip-arrow-right;
	@include tooltip-box-right; }


@mixin tooltip-direction($direction) {
	@if $direction == 'top' {
		@include tooltip-top; }
	@else if $direction == 'right' {
		@include tooltip-right; }
	@else if $direction == 'bottom' {
		@include tooltip-bottom; }
	@else if $direction == 'left' {
		@include tooltip-left; } }

@mixin tooltip-fade {
	&::before,
	&::after {
		transition: opacity .3s linear, visibility .3s linear; } }

@mixin tooltip-arrow {
	&::after {
		content: '';
		border-style: solid;
		border-width: $tooltip-arrow-size;
		border-color: rgba($tooltip-background-color, $tooltip-background-opacity) transparent transparent transparent;
		margin-bottom: $tooltip-arrow-size * -1 + 1; }
	@include tooltip-arrow-top; }

@mixin tooltip-box {
	&::before {
		background: rgba($tooltip-background-color, $tooltip-background-opacity);
		border-radius: $tooltip-radius;
		content: attr(data-tooltip);
		padding: $tooltip-padding;
		text-overflow: ellipsis;
		white-space: pre; }
	@include tooltip-box-top; }

@mixin tooltip-multiline {
	&::before {
		height: auto;
		width: $tooltip-max-width;
		max-width: $tooltip-max-width;
		text-overflow: clip;
		white-space: normal;
		word-break: keep-all; } }

[data-tooltip] {
	&:not(.is-loading),
	&:not(.is-disabled),
	&:not([disabled]) {
		cursor: pointer;
		overflow: visible;
		position: relative;
		z-index: 1;

		&::before,
		&::after {
			box-sizing: border-box;
			color: $tooltip-color;
			display: inline-block;
			font-family: $tooltip-font-family;
			font-size: $tooltip-font-size;
			hyphens: auto;
			opacity: 0;
			overflow: hidden;
			pointer-events: none;
			position: absolute;
			visibility: hidden;
			z-index: $tooltip-z-index; }

		@include tooltip-arrow;
		@include tooltip-box;

		&.has-tooltip-bottom {
			@include tooltip-direction('bottom'); }

		&.has-tooltip-left {
			@include tooltip-direction('left'); }

		&.has-tooltip-right {
			@include tooltip-direction('right'); }

		&.has-tooltip-multiline {
			@include tooltip-multiline; }

		@each $name, $pair in $colors {
			$color: nth($pair, 1);
			$color-invert: nth($pair, 2);
			&.has-tooltip-#{$name} {
				&:not(.has-tooltip-bottom),
				&:not(.has-tooltip-left),
				&:not(.has-tooltip-right) {
					&::after {
						border-color: rgba($color, $tooltip-background-opacity) transparent transparent transparent; } }
				&.has-tooltip-bottom {
					&::after {
						border-color: transparent transparent rgba($color, $tooltip-background-opacity) transparent; } }
				&.has-tooltip-left {
					&::after {
						border-color: transparent transparent transparent rgba($color, $tooltip-background-opacity); } }
				&.has-tooltip-right {
					&::after {
						border-color: transparent rgba($color, $tooltip-background-opacity) transparent transparent; } }
				&:before {
					background-color: rgba($color, $tooltip-background-opacity);
					color: $color-invert; } } }

		@include tooltip-hover {
			opacity: 1;
			visibility: visible; }

		&.has-tooltip-fade {
			@include tooltip-fade; } } }

@each $direction in top, right, bottom, left {
	@include mobile {
		.has-tooltip-#{$direction}-mobile {
			@include tooltip-direction(#{$direction}); } }
	@include tablet {
		.has-tooltip-#{$direction}-tablet {
			@include tooltip-direction(#{$direction}); } }
	@include tablet-only {
		.has-tooltip-#{$direction}-tablet-only {
			@include tooltip-direction(#{$direction}); } }
	@include touch {
		.has-tooltip-#{$direction}-touch {
			@include tooltip-direction(#{$direction}); } }
	@include desktop {
		.has-tooltip-#{$direction}-desktop {
			@include tooltip-direction(#{$direction}); } }
	@include desktop-only {
		.has-tooltip-#{$direction}-desktop-only {
			@include tooltip-direction(#{$direction}); } }
	@include until-widescreen {
		.has-tooltip-#{$direction}-until-widescreen {
			@include tooltip-direction(#{$direction}); } }
	@include widescreen {
		.has-tooltip-#{$direction}-widescreen {
			@include tooltip-direction(#{$direction}); } }
	@include widescreen-only {
		.has-tooltip-#{$direction}-widescreen-only {
			@include tooltip-direction(#{$direction}); } }
	@include until-fullhd {
		.has-tooltip-#{$direction}-until-fullhd {
			@include tooltip-direction(#{$direction}); } }
	@include fullhd {
		.has-tooltip-#{$direction}-fullhd {
			@include tooltip-direction(#{$direction}); } } }
